 "content": "def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = next((v for v, n in counts.most_common() if v != background), background)
    rows = {r for r in range(h) if all(v == foreground for v in grid[r])}
    cols = {c for c in range(w) if all(grid[r][c] == foreground for r in range(h))}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if (r in rows or c in cols) and grid[r][c] == foreground:
